-- Cambodia administrative divisions (gazetteer), PostgreSQL
-- Source: NCDD Gazetteer Database Online, https://db.ncdd.gov.kh/gazetteer/view/index.castle
-- Retrieved: 2026-11-15
-- Rows: 25 provinces, 210 districts, 1652 communes, 14578 villages
-- Unofficial copy. NCDD publishes no licence for this data. Generated by scripts/update.py; do not edit by hand.

BEGIN;

DROP TABLE IF EXISTS locations;
DROP TABLE IF EXISTS location_types;

CREATE TABLE location_types (
  id      smallint PRIMARY KEY,
  level   smallint NOT NULL CHECK (level BETWEEN 1 AND 4),
  name_km text     NOT NULL UNIQUE,
  name_en text     NOT NULL
);

CREATE TABLE locations (
  code        varchar(8)  PRIMARY KEY,
  parent_code varchar(8)  REFERENCES locations (code),
  level       smallint    NOT NULL CHECK (level BETWEEN 1 AND 4),
  type_id     smallint    NOT NULL REFERENCES location_types (id),
  name_km     text        NOT NULL,
  name_en     text
);
CREATE INDEX locations_parent_code_idx ON locations (parent_code);
CREATE INDEX locations_level_idx ON locations (level);
CREATE INDEX locations_type_id_idx ON locations (type_id);

COMMENT ON COLUMN locations.code IS 'Official NCDD code, zero-padded: 2 province, 4 district, 6 commune, 8 village';
COMMENT ON COLUMN locations.parent_code IS 'Code of the parent division; NULL for provinces';
COMMENT ON COLUMN locations.level IS '1 province, 2 district, 3 commune, 4 village';
COMMENT ON COLUMN locations.name_en IS 'NULL when NCDD has no English name yet';



































COMMIT;
